#!/bin/sh
# Refresh phpMyAdmin code in the shared volume, write its config, start php-fpm.
set -eu

APP=/var/www/phpmyadmin
: "${PMA_DB_HOST:?}"

# 1. The volume only holds code (shared read-only with nginx for CSS/JS), so
#    it is replaced on every start: a new image version is applied right away.
#    Files stay owned by root: PHP workers (www-data) can't modify the code.
echo "[entrypoint] Refreshing phpMyAdmin files"
find "$APP" -mindepth 1 -delete
cp -a /usr/src/phpmyadmin/. "$APP/"

# 2. config.inc.php, generated by PHP itself: var_export() escapes values
#    correctly. Users log in with their own MariaDB account (cookie auth), so
#    no database password is stored here.
echo "[entrypoint] Writing config.inc.php"
php83 > "$APP/config.inc.php" <<'PHP'
<?php
$cfg = [
    // Key used to encrypt the login cookie (32 bytes, generated by Ansible)
    'blowfish_secret' => rtrim(file_get_contents('/run/secrets/pma_blowfish_secret'), "\r\n"),
    'TempDir' => '/tmp/phpmyadmin',
    'VersionCheck' => false,          // no calls to phpmyadmin.net
    'SendErrorReports' => 'never',
    'Servers' => [1 => [
        'host' => getenv('PMA_DB_HOST'),
        'port' => '3306',
        'auth_type' => 'cookie',      // login form, nothing stored
        'AllowNoPassword' => false,
        'AllowRoot' => false,         // root can't log in through the web UI
    ]],
];
echo "<?php\n// Generated at container start by entrypoint.sh\n\$cfg = " . var_export($cfg, true) . ";\n";
PHP
# Readable by php-fpm (group www-data), not by nginx or anyone else
chown root:www-data "$APP/config.inc.php"
chmod 640 "$APP/config.inc.php"

mkdir -p /tmp/phpmyadmin
chown www-data:www-data /tmp/phpmyadmin

echo "[entrypoint] Starting php-fpm"
exec php-fpm83 -F
